
create schema ascent_game;
revoke all on schema ascent_game from public, anon, authenticated;
create table ascent_game.lexicon (clue text primary key, links jsonb not null);
create table ascent_game.boards (id integer primary key, target text not null, clues text[] not null check(cardinality(clues)=6));
create table ascent_game.runs (day date not null, ticket uuid not null, history jsonb not null default '[]', total integer not null default 0, primary key(day,ticket));
create index ascent_completed on ascent_game.runs(day,total) where jsonb_array_length(history)=5;
alter table ascent_game.lexicon enable row level security;
alter table ascent_game.boards enable row level security;
alter table ascent_game.runs enable row level security;
