create function ascent_game.route(d date) returns integer[] language sql stable set search_path='' as $$
select array(select id from (select distinct on (target) id,target,md5(d::text||':'||id::text) k from ascent_game.boards order by target,k) picked order by k limit 5);
$$;
create function public.ascent_daily(p_ticket uuid,p_day date default null,p_round int default null,p_guess text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
 d date:=(clock_timestamp() at time zone 'America/Los_Angeles')::date;
 dayroute integer[];
 h jsonb;
 total_points integer;
 ix int;
 b ascent_game.boards%rowtype;
 g text;
 links jsonb;
 perfect_links jsonb;
 hits int;
 pairs int;
 score int;
 crowd jsonb;
begin
 if p_ticket is null then raise exception 'Missing climb identifier'; end if;
 dayroute:=ascent_game.route(d);
 if p_guess is not null and p_day=d then
   g:=lower(btrim(p_guess));
   if g !~ '^[a-z]{1,36}$' or p_round is null or p_round not between 1 and 5 then raise exception 'Enter one word'; end if;
   insert into ascent_game.runs(day,ticket) values(d,p_ticket) on conflict do nothing;
 end if;
 select history,total into h,total_points from ascent_game.runs where day=d and ticket=p_ticket for update;
 h:=coalesce(h,'[]'::jsonb); total_points:=coalesce(total_points,0);
 ix:=jsonb_array_length(h)+1;
 if ix<=5 and p_guess is not null and p_day=d and ix=p_round then
   select * into strict b from ascent_game.boards where id=dayroute[ix];
   select coalesce(jsonb_object_agg(clue,links_by_word->g) filter(where links_by_word ? g and g<>all(b.clues)),'{}'::jsonb),
      jsonb_object_agg(clue,links_by_word->b.target)
   into links,perfect_links from (select clue,l.links links_by_word from ascent_game.lexicon l where clue=any(b.clues)) s;
   select count(*) into hits from jsonb_object_keys(links);
   select count(*) into pairs from generate_series(1,3) i where links ? b.clues[i] and links ? b.clues[i+3];
   score:=case when hits=6 then 200 else 10*(hits*(hits+1)/2+pairs) end;
   h:=h||jsonb_build_array(jsonb_build_object('guess',g,'clues',b.clues,'links',links,'points',score,'target',b.target,'solution',perfect_links));
   total_points:=total_points+score;
   update ascent_game.runs set history=h,total=total_points where day=d and ticket=p_ticket;
   ix:=ix+1;
 end if;
 if ix=6 then
   select jsonb_build_object('average',round(avg(total)),'players',count(*)) into crowd from ascent_game.runs where day=d and jsonb_array_length(history)=5;
   return jsonb_build_object('day',d,'history',h,'results',crowd||jsonb_build_object('score',total_points));
 end if;
 return jsonb_build_object('day',d,'history',h,'clues',(select clues from ascent_game.boards where id=dayroute[ix]));
end;
$$;
revoke all on function public.ascent_daily(uuid,date,int,text) from public;
grant execute on function public.ascent_daily(uuid,date,int,text) to anon,authenticated;
notify pgrst,'reload schema';
